tests.pseudocode:
fset := token.NewFileSet()
pkgs, _ := parser.ParseDir(fset, "codefix", nil, 0)
for _, pkg := range pkgs {
  for _, f := range pkg.Files {
    for _, d := range f.Decls {
      if fn, ok := d.(*ast.FuncDecl); ok {
        assert fn.Name.Name not in ["untrackedNow", "commitOwn", "commitOwnHooks", "ownChange", "parkWork", "returnCheckout", "background", "invalidate", "runChecks", "branchPrefix"]
      }
    }
  }
}
assert !fileExists("codefix/untracked.go")

fset := token.NewFileSet()
pkgs, _ := parser.ParseDir(fset, "codefix", nil, 0)
deleted := []string{"analysisSystemPrompt", "implementSystemPrompt", "reportBlock", "baselineBlock", "criteriaBlock", "contextBlock", "analysisPrompt", "implementPrompt", "instructionsBlock", "projectInstructions"}
for _, pkg := range pkgs {
  for _, f := range pkg.Files {
    for _, d := range f.Decls {
      name := declName(d)
      assert name not in deleted
    }
  }
}
assert !fileExists("codefix/prompts.go")

fset := token.NewFileSet()
pkgs, _ := parser.ParseDir(fset, "codefix", nil, 0)
for _, pkg := range pkgs {
  for _, f := range pkg.Files {
    for _, d := range f.Decls {
      if gen, ok := d.(*ast.GenDecl); ok && gen.Tok == token.CONST {
        for _, spec := range gen.Specs {
          vs := spec.(*ast.ValueSpec)
          for _, v := range vs.Values {
            if lit, ok := v.(*ast.BasicLit); ok && lit.Kind == token.STRING {
              s := lit.Value
              if isModelFacing(s) {
                assert !hasMultipleSentences(s)
              }
            }
          }
        }
      }
    }
  }
}

transcript := buildTranscript(12)
pruned := pruningTransform(transcript, currentTurn: 12, threshold: 8)
for i := 0; i < 4; i++ {
  assert isPrunedStub(pruned[i])
  assert strings.Contains(pruned[i].Content, pruned[i].ToolName)
}

profile := lang.Profile{InlineTests: true, Targeted: lang.Command{Base: "cargo test"}}
changed := []string{"src/lib.rs"}
outline := []Declaration{{Name: "parse", Lines: [10, 30]}, {Name: "tests", Lines: [32, 60], IsTest: true}}
rc, err := targetedRevert(ctx, profile, ledger, runner, outline)
assert err == nil
assert slices.Contains(rc.Declarations, "parse")
assert !slices.Contains(rc.Declarations, "tests")

profile := lang.Profile{InlineTests: true}
changed := []string{"src/broken.rs"}
rc, err := targetedRevert(ctx, profile, ledger, runner, outlineError: true)
assert err == nil
assert slices.Contains(rc.Reverted, "src/broken.rs")
assert rc.Mode == "targeted"

detection := lang.Detection{Primary: goProfile, All: [goProfile, pythonProfile]}
opts := validOptions(detection: detection)
result, _ := codefix.Run(ctx, opts)
assert result.Language.Primary == "go"
assert result.Language.Detected == []string{"go", "python"}
assert result.Language.Verify.Source == "makefile"

old := loadJSON("cmd/fix/testdata/schema.golden.json.before")
new := loadJSON("cmd/fix/testdata/schema.golden.json")
for key, typ := range old.Fields {
  assert new.Fields[key] == typ
}
additive := setDiff(new.Fields, old.Fields)
allowed := set{"language", "revert_check.mode", "revert_check.declarations", "timings[].cached", "usage.phases[].pruned_tokens", "prompt_templates", "prompts_dir", "prompts_not_written"}
assert additive.isSubsetOf(allowed)
